/// <summary>
/// CB434_BasePriceVersion4StandardCosting, pass custom fields
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceUpdateValidJob))]
internal final class METGUPItemBasePriceUpdateValidJob_Extension
{
}

Method.Source:
/// <summary>
/// init custom fields
/// </summary>
/// <param name = "_selectionObject"></param>
protected void addBasePriceExtendedFields(SysDaSelection _selectionObject)
{
    next addBasePriceExtendedFields(_selectionObject);
    _selectionObject
        .add(fieldStr(GUPItemBasePrice, METVendClaimEnabled));
}

/// <summary>
/// CB434, after GUPItemBasePrice records are inserted, create standard costing entries
/// for all BasePriceInventoryCost records with no ToDate in this operation batch.
/// </summary>
/// <param name = "_operationGuid">Guid identifying the GUPItemBasePrice records inserted in this run</param>
public void postUpdateValidBasePrice(SysGuid _operationGuid)
{
    next postUpdateValidBasePrice(_operationGuid);

    GUPParameters gupParameters = GUPParameters::find();

    if (gupParameters.METCreateItemPrice)
    {
        GUPItemBasePrice itemBasePrice, itemBasePricePastRecord, itembasePriceUpdate;

        while select ItemId, PriceType, InventDimId, FromDate, ToDate, OperationGuid 
            from itemBasePrice
            where itemBasePrice.OperationGuid                   == _operationGuid
                && itemBasePrice.PriceType                      == GUPBasePriceType::BasePriceInventoryCost
                && itemBasePrice.FromDate                       <= systemDateGet()
                && itemBasePrice.METItemPriceActivationStatus   != METItemPriceActivationStatus::Completed
                && itemBasePrice.METItemPriceActivationStatus   != METItemPriceActivationStatus::Skipped
                && (itemBasePrice.ToDate                        == dateNull() || itemBasePrice.ToDate >= systemDateGet())
        notexists join itemBasePricePastRecord
            where itemBasePricePastRecord.OperationGuid  == itemBasePrice.OperationGuid
                && itemBasePricePastRecord.PriceType     == itemBasePrice.PriceType
                && itemBasePricePastRecord.ItemId        == itemBasePrice.ItemId
                && itemBasePricePastRecord.InventDimId   == itemBasePrice.InventDimId
                && itemBasePricePastRecord.FromDate      >  itemBasePrice.FromDate
                && itemBasePricePastRecord.FromDate      <= systemDateGet()
        {
            itembasePriceUpdate = GUPItemBasePrice::findByDateRanges(itemBasePrice.ItemId,
                                                            itemBasePrice.PriceType,
                                                            itemBasePrice.InventDimId,
                                                            itemBasePrice.FromDate,
                                                            itemBasePrice.ToDate,
                                                            itemBasePrice.OperationGuid,
                                                            false);

            if (itembasePriceUpdate.RecId)
            {
                itembasePriceUpdate.inventItemPriceCreation();
            }
        }
    }
}
